// The "subscriptions" feed (remote-content §3): a UNION of public, published
// videos from the LOCAL channels the user follows and the ingested remote
// videos of their ACCEPTED remote-channel follows, newest first, with the same
// discovery-card shape as the main feed. Remote cards are flagged remote and
// carry the origin domain + watch/stream URLs; instance mutes (the user's) and
// the admin instance blocklist hide remote rows.
func (q *Queries) ListSubscriptionVideos(ctx context.Context, arg ListSubscriptionVideosParams) ([]ListSubscriptionVideosRow, error) {
	rows, err := q.db.Query(ctx, listSubscriptionVideos, arg.FollowerID, arg.ResultOffset, arg.ResultLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSubscriptionVideosRow
	for rows.Next() {
		var i ListSubscriptionVideosRow
		if err := rows.Scan(
			&i.ID,
			&i.Remote,
			&i.ChannelID,
			&i.Title,
			&i.Description,
			&i.Privacy,
			&i.State,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Views,
			&i.HasThumbnail,
			&i.ChannelHandle,
			&i.ChannelDisplayName,
			&i.AuthorDisplayName,
			&i.DurationSeconds,
			&i.Domain,
			&i.WatchUrl,
			&i.StreamUrl,
			&i.IsSensitive,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listVideoIDsByOwner = `-- name: ListVideoIDsByOwner :many
SELECT v.id
FROM videos v
JOIN channels c ON c.id = v.channel_id
WHERE c.owner_id = $1
ORDER BY v.id
`

// Every video (any privacy/state) owned by a user, resolved via their channels.
// Drives the IPFS mirror's unlisted-toggle re-evaluation (spec §3): flipping a user
// unlisted must pull ALL their public videos (and derivatives) off the mirror, and
// re-listing re-pins the still-eligible ones. Returns ALL of the owner's videos —
// SyncVideo re-derives per-video eligibility (pin vs unpin) from committed state.
func (q *Queries) ListVideoIDsByOwner(ctx context.Context, ownerID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listVideoIDsByOwner, ownerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

